// TestSessionEndCondensation_UnrelatedCommitDoesNotLinkInterruptedSession pins
// why doctor is the retry path that matters. An interrupted eager condense
// leaves an ENDED session with no FilesTouched, and PrepareCommitMsg's content
// detection deliberately refuses to link that to a commit of unrelated files
// (stagedFilesOverlapWithContent has nothing to overlap). So the session is not
// swept up by the next commit, and it must not be duplicated either.
func TestSessionEndCondensation_UnrelatedCommitDoesNotLinkInterruptedSession(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)
	sess, snap := startEagerCondensableSession(t, env, "feature.go", "package main\n\nfunc Feature() {}\n")

	if err := env.SimulateSessionEnd(sess.ID); err != nil {
		t.Fatalf("SimulateSessionEnd failed: %v", err)
	}
	written := assertCheckpointCount(t, env, 1, "after session end")[0].CheckpointID

	forgeInterruptedCondensation(t, env, sess.ID, snap, written)

	env.WriteFile("unrelated.txt", "hand-written\n")
	env.GitCommitWithShadowHooksAsAgent("Unrelated hand-written change", "unrelated.txt")

	if trailer := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash()); trailer != "" {
		t.Errorf("unrelated commit got checkpoint trailer %q, want none", trailer)
	}
	if infos := assertCheckpointCount(t, env, 1, "an unrelated commit must not add a checkpoint"); infos[0].CheckpointID != written {
		t.Errorf("checkpoint %s survived, want %s", infos[0].CheckpointID, written)
	}
}

// TestSessionEndCondensation_AgentCommitDoesNotStrandInterruptedSession is the
// regression test for the gap this PR opens.
//
// postCommitProcessSessionLocked now bails out of the whole GitCommit transition
// whenever a session's reserved attempt ID differs from the commit's checkpoint
// ID. That makes PostCommit stop being the retry path it is documented to be —
// and tryAgentCommitFastPath cannot supply the reserved ID, because
// addTrailerForAgentCommit passes checkpointIDForSessions a slice holding only
// the one ACTIVE session it picked. So every agent commit mints a fresh ID and
// skips the interrupted session again, leaving it stranded until somebody runs
// `entire doctor` by hand (the exited-owner sweep in `entire status` excludes
// ENDED sessions).
//
// Before this PR, PostCommit condensed the interrupted session into the commit's
// checkpoint — duplicating, but never losing it.
func TestSessionEndCondensation_AgentCommitDoesNotStrandInterruptedSession(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)

	// The interrupted session: real condense, then rewound to the crash state.
	interrupted, snap := startEagerCondensableSession(t, env, "feature.go", "package main\n\nfunc Feature() {}\n")
	if err := env.SimulateSessionEnd(interrupted.ID); err != nil {
		t.Fatalf("SimulateSessionEnd failed: %v", err)
	}
	reserved := assertCheckpointCount(t, env, 1, "after session end")[0].CheckpointID
	forgeInterruptedCondensation(t, env, interrupted.ID, snap, reserved)

	// A second, live agent session commits its own work in the same worktree.
	live := env.NewSession()
	if err := env.SimulateUserPromptSubmit(live.ID); err != nil {
		t.Fatalf("live session user-prompt-submit failed: %v", err)
	}
	env.WriteFile("live.go", "package main\n\nfunc Live() {}\n")
	live.CreateTranscript("Write live.go", []FileChange{{Path: "live.go", Content: "package main\n\nfunc Live() {}\n"}})
	env.GitCommitWithShadowHooksAsAgent("Agent commit from the live session", "live.go")

	state, err := env.GetSessionState(interrupted.ID)
	if err != nil {
		t.Fatalf("GetSessionState failed: %v", err)
	}
	if state == nil {
		return // condensed and cleaned up entirely — also fine
	}
	if !state.CondensationAttemptID.IsEmpty() {
		t.Errorf("interrupted session still holds reservation %s: PostCommit skipped it instead of retrying",
			state.CondensationAttemptID)
	}
	if state.LastCheckpointID.IsEmpty() {
		t.Error("interrupted session was never condensed by the commit that followed it")
	}
	if infos := assertCheckpointCount(t, env, 1, "the retry must reuse the reserved checkpoint"); infos[0].CheckpointID != reserved {
		t.Errorf("checkpoint %s survived, want the reserved %s", infos[0].CheckpointID, reserved)
	}
}

// TestSessionEndCondensation_AdvancedLegacySessionGetsNewCheckpoint is the
// negative control for reuse: once a session has genuinely produced content
// beyond the orphaned checkpoint's range, reconciliation must mint a fresh
// checkpoint instead of overwriting. Otherwise "never duplicate" could be
// satisfied by quietly dropping the newer work.
//
// Uses the legacy (unreserved) shape on purpose. With a reservation present the
// retry deliberately reuses the ID and writes the superset range into it, which
// merges rather than duplicates; the content-comparison path is the one that has
// to make a judgement call.
func TestSessionEndCondensation_AdvancedLegacySessionGetsNewCheckpoint(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)
	sess, snap := startEagerCondensableSession(t, env, "feature.go", "package main\n\nfunc Feature() {}\n")

	if err := env.SimulateSessionEnd(sess.ID); err != nil {
		t.Fatalf("SimulateSessionEnd failed: %v", err)
	}
	orphan := assertCheckpointCount(t, env, 1, "after session end")[0].CheckpointID

	forgeInterruptedCondensation(t, env, sess.ID, snap, id.EmptyCheckpointID)

	// The session comes back and does more work beyond the orphan's range.
	if err := env.SimulateUserPromptSubmit(sess.ID); err != nil {
		t.Fatalf("second user-prompt-submit failed: %v", err)
	}
	advanced := "package main\n\nfunc Feature() {}\n\nfunc More() {}\n"
	env.WriteFile("feature.go", advanced)
	sess.CreateTranscript("Add More", []FileChange{{Path: "feature.go", Content: advanced}})
	if err := env.SimulateStop(sess.ID, sess.TranscriptPath); err != nil {
		t.Fatalf("second stop failed: %v", err)
	}

	env.RunCLI("doctor", "--force")

	infos := listStoredCheckpoints(t, env)
	if len(infos) != 2 {
		ids := make([]string, 0, len(infos))
		for _, info := range infos {
			ids = append(ids, info.CheckpointID.String())
		}
		t.Fatalf("advanced session got %d checkpoint(s) %v, want 2", len(infos), ids)
	}
	kept := false
	for _, info := range infos {
		if info.CheckpointID == orphan {
			kept = true
		}
	}
	if !kept {
		t.Errorf("the orphaned checkpoint %s was overwritten instead of kept alongside the new one", orphan)
	}
}
